              "{\"articleBody\":\"”\",\"articleSection\":[\"business\",\"economy\"],\"author\":[{\"name\":\"Laura He\"}],\"dateModified\":\"2019-07-15T11:19:20Z\",\"headline\":\"China’s economic growth slumps to lowest in 27 years as the trade war hits\",\"alternativeHeadline\":\"China GDP growth slumps to lowest in 27 years as the trade war hits\",\"inLanguage\":\"en\",\"publisher\":{\"name\":\"CNN\",\"foundingDate\":\"1980-06-01\",\"sameAs\":[\"https://www.facebook.com/cnn/\",\"https://x.com/CNN\",\"https://www.tiktok.com/@cnn\",\"https://www.instagram.com/cnn/\",\"https://www.youtube.com/cnn\"]},\"timeRequired\":\"P0Y0M0DT0H2M38S\",\"wordCount\":596,\"video\":[{\"dateModified\":\"2019-06-27T14:01:47Z\",\"uploadDate\":\"2019-06-27T14:01:47Z\",\"duration\":\"PT00H01M53S\",\"caption\":[{\"encodingFormat\":\"vtt\",\"inLanguage\":\"en\"},{\"encodingFormat\":\"srt\",\"inLanguage\":\"en\"}],\"inLanguage\":\"en\",\"name\":\"China made tariff demand before Xi, Trump G20 meeting\",\"headline\":\"China made tariff demand before Xi, Trump G20 meeting\",\"description\":\"CNN's Nic Robertson reports that Beijing wanted a guarantee that the US would not enact additional tariffs before Chinese President Xi Jinping would agree to meet President Donald Trump at the G20 summit in Osaka, Japan.\"}],\"datePublished\":\"2019-07-15T05:45:40Z\",\"isAccessibleForFree\":false,\"hasPart\":{\"isAccessibleForFree\":false}}"
